                dist[r][c] = (0, grid[r][c])
                q.append((r, c, grid[r][c]))
    while q:
        r, c, color = q.popleft()
        d = dist[r][c][0]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] == 0:
                continue
            candidate = (d + 1, color)
            if dist[nr][nc] is None or candidate < dist[nr][nc]:
                dist[nr][nc] = candidate
                q.append((nr, nc, color))
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 1 and all(
                grid[r + dr][c + dc] != 0
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
            ) and dist[r][c] is not None:
                out[r][c] = dist[r][c][1]
